insert into public.tutors
  (id, name, grade, tagline, subjects, joined_at, hue, courses, availability, is_founder)
values
  ('founder', 'Aditya Gaur', '10th grade', '', array['python', 'ai']::text[], '2026-09-01T00:00:00.000Z', 212, '[]'::jsonb, null, true),
  ('roster-sohail', 'Sohail T.', '10th grade', 'Algebra is a handful of rules used over and over. I teach the rules.', array['math']::text[], '2026-10-12T00:00:00.000Z', 26, '[{"title":"Algebra 1","subject":"math","summary":"Variables and moving things around an equation, then linear and polynomial forms, factoring, quadratics, systems of equations, radicals and exponent rules.","topics":["Equations","Factoring","Quadratics","Systems","Exponents"]},{"title":"Algebra 2","subject":"math","summary":"Higher-degree polynomials, the forms of a parabola, three-equation systems, the complex plane, rational and exponential functions, the unit circle, polynomial division and sequences.","topics":["Polynomials","Complex numbers","Unit circle","Sequences"]}]'::jsonb, null, false),
  ('roster-abhiram', 'Abhiram K.', '10th grade', 'Geometry through trig, algebra through Algebra 2.', array['math']::text[], '2026-10-06T00:00:00.000Z', 40, '[{"title":"Geometry and Algebra","subject":"math","summary":"Help with whatever unit you are on in Geometry (up to trigonometry) or Algebra 1 and 2.","topics":["Geometry","Trigonometry","Algebra 1","Algebra 2"]}]'::jsonb, 'Tuesdays and Wednesdays, 6–8pm', false),
  ('roster-akil', 'Akil', '10th grade', 'I follow whatever your class is doing and get you a little ahead of it.', array['math', 'spanish']::text[], '2026-10-06T00:00:00.000Z', 150, '[{"title":"Geometric Foundations","subject":"math","summary":"Geometry and everything before it, paced to your class. We go back over lessons you missed and spend the most time on whatever you find hardest."},{"title":"Algebraic Foundations","subject":"math","summary":"The algebra basics your class assumes you know, practiced until they stick."},{"title":"Basic Spanish Essentials","subject":"spanish","summary":"Spanish 1 and 2: vocabulary, grammar and enough practice to keep up in class."}]'::jsonb, 'Any day after 5pm · 90-minute classes, twice a week works best', false),
  ('roster-haggai', 'Haggai K.', '10th grade', 'Grammar, essays and reading closely. No homework, ever.', array['english']::text[], '2026-10-06T00:00:00.000Z', 318, '[{"title":"Foundational English Skills","subject":"english","summary":"Grammar rules, essay writing and story analysis. We read short stories and excerpts from well-known books, then write short essays on them to practice both.","topics":["Grammar","Essays","Literary analysis"]}]'::jsonb, 'Tuesdays, 7:30–8:30pm · every other week', false),
  ('roster-ayden', 'Ayden J.', '10th grade', 'Design it on the computer first, so you only build it once.', array['cad']::text[], '2026-09-06T00:00:00.000Z', 68, '[{"title":"Introduction to Engineering Design and CAD","subject":"cad","summary":"How engineers go from an idea to a part you can manufacture. You sketch a shape, constrain it with dimensions, and extrude it into a 3D model, then change one number and watch the whole design update.","topics":["Sketching","Constraints","Extrusions","Design process"]}]'::jsonb, null, false)
